import json, urllib.request


def txt(name):
    r = json.load(urllib.request.urlopen(f"https://dns.google/resolve?name={name}&type=TXT", timeout=15))
    return [a["data"].replace('" "', "").strip('"') for a in r.get("Answer", [])]


def spf(name):
    return next((t for t in txt(name) if t.startswith("v=spf1")), "")


def count(name, depth=0):
    n = 0
    for term in spf(name).split()[1:]:
        if term.startswith(("include:", "redirect=")):
            child = term.split(":", 1)[-1].split("=", 1)[-1]
            sub = count(child, depth + 1)
            print("  " * depth + f"{term:30} +1 (안쪽 +{sub})")
            n += 1 + sub
        elif term.split(":")[0].lstrip("+-~?") in ("a", "mx", "exists", "ptr"):
            n += 1
    return n


print("DNS 조회 수:", count("musinsa.com"), "/ 한도 10")
